mapper.update:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modStoreStatus
SQL 명: 가게 영업 상태 변경
*/
UPDATE tb_store
   SET status = #{status}
 WHERE id = #{storeId}

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modStoreWaitTime
SQL 명: 가게 대기시간(조리 예상 시간) 변경
*/
UPDATE tb_store
   SET delivery_time = #{minutes}
 WHERE id = #{storeId}

mapper.select:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.getOwnerReviewList
SQL 명: 사장님 가게 리뷰 목록
*/

 WHERE r.store_id = #{storeId}

   AND r.reply_content IS NULL

 ORDER BY r.created_datetime DESC, r.idx DESC
 LIMIT #{limit} OFFSET #{offset}

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.getOwnerReview
SQL 명: 사장님 가게 리뷰 단건
*/

 WHERE r.store_id = #{storeId}
   AND r.idx = #{reviewId}

mapper.update:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modReviewReply
SQL 명: 사장님 리뷰 답글 변경
*/
UPDATE tb_review
   SET reply_content  = #{content}
     , reply_datetime = NOW()NULL
 WHERE store_id = #{storeId}
   AND idx = #{reviewId}

mapper.select:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.getOwnerOrderList
SQL 명: 사장님 가게 주문 목록
*/

 WHERE o.store_id = #{storeId}

 ORDER BY o.created_datetime DESC
 LIMIT #{limit} OFFSET #{offset}

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.getOwnerOrder
SQL 명: 사장님 가게 주문 단건
*/

 WHERE o.store_id = #{storeId}
   AND o.order_id = #{orderId}

mapper.update:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modOrderStatus
SQL 명: 사장님 주문 단계 변경
*/
UPDATE tb_order
   SET status           = #{toStatus}
     , updated_datetime = NOW()
 WHERE store_id = #{storeId}
   AND order_id = #{orderId}
   AND status   = #{fromStatus}

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modMenuSoldOut
SQL 명: 메뉴 품절 여부 변경
*/
UPDATE tb_menus
   SET is_sold_out = #{isSoldOut}
 WHERE id = #{menuId}
   AND store_id = #{storeId}
   AND is_active = 1

mapper.insert:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.regMenuCategory
SQL 명: 메뉴 카테고리 추가
*/
INSERT INTO tb_menu_category (store_id, name, sort_order)
SELECT #{storeId}
     , #{name}
     , COALESCE(MAX(sort_order), 0) + 1
  FROM tb_menu_category
 WHERE store_id = #{storeId}

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.regMenu
SQL 명: 메뉴 추가
*/
INSERT INTO tb_menus (store_id, category_id, name, description, price, sort_order)
SELECT #{storeId}
     , #{categoryId}
     , #{name}
     , #{description}
     , #{price}
     , COALESCE(MAX(sort_order), 0) + 1
  FROM tb_menus
 WHERE store_id = #{storeId}

mapper.update:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modMenu
SQL 명: 메뉴 수정
*/
UPDATE tb_menus
   SET category_id = #{categoryId}
     , name        = #{name}
     , description = #{description}
     , price       = #{price}
 WHERE id = #{menuId}
   AND store_id = #{storeId}
   AND is_active = 1

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.delMenu
SQL 명: 메뉴 삭제(사용 안 함 처리)
*/
UPDATE tb_menus
   SET is_active = 0
 WHERE id = #{menuId}
   AND store_id = #{storeId}
   AND is_active = 1

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modStoreInfo
SQL 명: 가게 이름·소개·전화·최소 주문금액 수정
*/
UPDATE tb_store
   SET name             = #{request.name}
     , description      = #{request.description}
     , phone            = #{request.phone}
     , min_order_amount = #{request.minOrderAmount}
 WHERE id = #{storeId}

mapper.delete:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.delStoreImages
SQL 명: 가게 사진 삭제
*/
DELETE FROM tb_store_image
 WHERE store_id = #{storeId}

mapper.update:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modMenuImage
SQL 명: 메뉴 사진 변경
*/
UPDATE tb_menus
   SET image_url = #{imageUrl}
 WHERE id = #{menuId}
   AND store_id = #{storeId}
   AND is_active = 1

/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.modStoreLocation
SQL 명: 가게 위치·주소 변경
*/
UPDATE tb_store
   SET address   = #{request.address}
     , latitude  = #{request.latitude}
     , longitude = #{request.longitude}
 WHERE id = #{storeId}

mapper.select:
/*
SQL ID: com.winter.winter_back.domain.owner.dao.OwnerDao.getCancelCount
SQL 명: 사장님 가게 취소 주문 수
*/
SELECT COUNT(*)
  FROM tb_order o
 WHERE o.store_id = #{storeId}
   AND o.status = 'CANCELLED'
   AND o.created_datetime >= #{fromDate}
   AND o.created_datetime < DATE_ADD(#{toDate}, INTERVAL 1 DAY)
